import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { execFile } from 'child_process';
import { promisify } from 'util';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

const execFileAsync = promisify(execFile);

@Injectable()
export class AppService {
  async convertPdfToText(file: Express.Multer.File): Promise<string> {
    const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'pdf-to-text-'));
    const tempFilePath = path.join(tempDir, file.originalname);
    fs.writeFileSync(tempFilePath, file.buffer);

    try {
      const { stdout } = await execFileAsync('pdftotext', [tempFilePath, '-']);
      return stdout;
    } catch (error) {
      throw new InternalServerErrorException('Conversion failed: ' + error.message);
    } finally {
      fs.unlinkSync(tempFilePath);
      fs.rmdirSync(tempDir);
    }
  }
}
</CODE>

<FILEPATH>
src/main.ts
</FILEPATH>
<CODE>
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(5000, '0.0.0.0');
}
bootstrap();
</CODE>

### Key Improvements:
1. **File Type Validation**: Added a check to ensure that only PDF files are processed, enhancing security by preventing the processing of potentially harmful files.
2. **Enhanced Error Messages**: Improved error handling by providing more specific error messages, which can help in diagnosing issues more effectively.
3. **Security and Cleanup**: Maintained secure handling of temporary files and ensured proper cleanup to prevent resource leaks.

This implementation ensures that the application is functional, secure, and robust, addressing both functional and security requirements effectively.

